/// Lean `String.trimAscii`: strips ' ', '\t', '\r', '\n' at both ends, by code point.
func leanTrimAscii(_ s: String) -> String {
    let ws: Set<UInt32> = [0x20, 0x09, 0x0d, 0x0a]
    var sc = Substring.UnicodeScalarView(s.unicodeScalars)
    while let f = sc.first, ws.contains(f.value) { sc = sc.dropFirst() }
    while let l = sc.last, ws.contains(l.value) { sc = sc.dropLast() }
    return String(sc)
}

struct Model {
    var todos: [Todo]
    var draft: String
    var nextId: Int
    var filter: Filter
}

enum Msg {
    case setDraft(String)
    case add
    /// Set a todo's done flag to the toggle's new value (the value is authoritative, not a flip).
    case setDone(Int, Bool)
    case delete(Int)
    case setFilter(Filter)
    case clearDone
}

struct Todo {
    var id: Int
    var title: String
    var done: Bool
}

enum Filter: Equatable {
    case all
    case active
    case done
}

enum TodoApp: ElmApp {
