        case Msg.delete(let id):
            return Model(todos: x_1.todos.filter({ (t: Todo) -> Bool in (t.id != id) }), draft: x_1.draft, nextId: x_1.nextId, filter: x_1.filter)
        case Msg.setFilter(let f):
            return Model(todos: x_1.todos, draft: x_1.draft, nextId: x_1.nextId, filter: f)
        case Msg.clearDone:
            return Model(todos: x_1.todos.filter({ (t: Todo) -> Bool in !t.done }), draft: x_1.draft, nextId: x_1.nextId, filter: x_1.filter)
        }
