            Html<Msg>.text("Todos", TextStyle.title),
            Html<Msg>.row([
                Html<Msg>.field(placeholder: "What needs doing?", value: m.draft, onInput: { (s: String) -> Msg in Msg.setDraft(s) }, onSubmit: Optional<Msg>.some(Msg.add)),
                Html<Msg>.button(label: "Add", role: ButtonRole.primary, onClick: (Self.trimTitle(m.draft).isEmpty ? Optional<Msg>.none : Optional<Msg>.some(Msg.add)))
