            Html<Msg>.col(Self.visible(m).map({ (t: Todo) -> Html<Msg> in Self.todoRow(t) })),
            Html<Msg>.divider,
            Html<Msg>.row([
                Self.filterButton(m, Filter.all, "All"),
                Self.filterButton(m, Filter.active, "Active"),
                Self.filterButton(m, Filter.done, "Done")
            ]),
            Html<Msg>.text((String(Self.remaining(m)) + " left"), TextStyle.caption),
            Html<Msg>.button(label: "Clear done", role: ButtonRole.destructive, onClick: (m.todos.contains(where: { (x: Todo) -> Bool in x.done }) ? Optional<Msg>.some(Msg.clearDone) : Optional<Msg>.none))
