    static func visible(_ m: Model) -> [Todo] {
        let d = m.filter
        switch d {
        case Filter.all:
            return m.todos
        case Filter.active:
            return m.todos.filter({ (t: Todo) -> Bool in !t.done })
        case Filter.done:
            return m.todos.filter({ (t: Todo) -> Bool in t.done })
        }
